#include <bits/stdc++.h>
using namespace std;

#define rep(i, a, b) for(int i = (a); i < (b); i++)
#define all(v) (v).begin(), (v).end()

typedef long long ll;

const int MAXN = 600;

ll mod;
struct BigInt {
    ll v;
    BigInt() : v(0) {}
    BigInt(ll _v) { v = _v % mod; if (v < 0) v += mod; }
    BigInt operator+(const BigInt &b) const { return BigInt((v + b.v) % mod); }
    BigInt operator-(const BigInt &b) const { return BigInt((v - b.v + mod) % mod); }
    BigInt operator*(const BigInt &b) const { return BigInt((v * b.v) % mod); }
    BigInt pow(ll e) const {
        BigInt res(1), base(v);
        while (e > 0) {
            if (e & 1) res = res * base;
            base = base * base;
            e >>= 1;
        }
        return res;
    }
    BigInt inv() const { return pow(mod - 2); }
};

BigInt comb[MAXN][MAXN];
BigInt a[MAXN], c[MAXN];
BigInt dp[MAXN][MAXN][2], dpc[MAXN][MAXN][2];

ll sum_range(ll l, ll r) {
    if (l > r) return 0;
    return (l + r) * (r - l + 1) / 2;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m >> mod;

    for (int i = 0; i <= m; ++i) {
        for (int j = 0; j <= i; ++j) {
            comb[i][j] = (j == 0 || j == i) ? BigInt(1) : comb[i - 1][j - 1] + comb[i - 1][j];
        }
    }

    a[0] = BigInt(0); c[0] = BigInt(1);
    a[1] = BigInt(0); c[1] = BigInt(2);

    for (int i = 2; i <= m; ++i) {
        BigInt tmp(0), tmpc(0);
        for (int l = 0; l <= i; ++l) {
            int r = i - 1 - l;
            tmp = tmp + c[l] * c[r] * BigInt(sum_range(1, l) + sum_range(1, r))
                * comb[i - 1][l] + (a[l] * c[r] + a[r] * c[l]) * comb[i - 1][l] * BigInt(i + 1);
            tmpc = tmpc + c[l] * c[r] * BigInt(i + 1) * comb[i - 1][l];
        }
        a[i] = tmp;
        c[i] = tmpc;
    }

    for (int i = 0; i <= n; ++i)
        for (int j = 0; j <= m; ++j)
            for (int k = 0; k < 2; ++k)
                dpc[i][j][k] = BigInt(0);
    dpc[0][0][0] = BigInt(1);

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            dpc[i][j][0] = dpc[i - 1][j][0] + dpc[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                dpc[i][j][1] = dpc[i][j][1] + c[k] * comb[j][k] * dpc[i - k][j - k][0];
            }
        }
    }

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= m; ++j) {
            if (j > i) continue;
            dp[i][j][0] = dp[i - 1][j][0] + dp[i - 1][j][1];
            for (int k = 1; k <= j; ++k) {
                dp[i][j][1] = dp[i][j][1] + a[k] * comb[j][k] * dpc[i - k][j - k][0]
                                + dp[i - k][j - k][0] * c[k] * comb[j][k];
            }
        }
    }

    cout << (dp[n][m][0] + dp[n][m][1]).v << "\n";

    return 0;
}
